CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,value_type TEXT NOT NULL CHECK(value_type IN('string','integer','boolean','json')),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS security_policies(id TEXT PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE,mode TEXT NOT NULL CHECK(mode IN('readonly','ask_before_execute','allow_safe_commands','manual_only')),allow_rules_json TEXT NOT NULL DEFAULT '[]',deny_rules_json TEXT NOT NULL DEFAULT '[]',limits_json TEXT NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_policy_active ON security_policies(is_active) WHERE is_active=1;
CREATE TABLE IF NOT EXISTS hosts(id TEXT PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE,connection_type TEXT NOT NULL CHECK(connection_type IN('direct_ssh','bastion_endpoint')),address TEXT NOT NULL,port INTEGER NOT NULL CHECK(port BETWEEN 1 AND 65535),username TEXT NOT NULL,auth_method TEXT NOT NULL CHECK(auth_method IN('password','private_key','ssh_agent')),group_name TEXT,is_production INTEGER NOT NULL DEFAULT 0,endpoint_fingerprint TEXT,remote_identity_hmac TEXT,policy_id TEXT NOT NULL,notes TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,FOREIGN KEY(policy_id) REFERENCES security_policies(id));
CREATE UNIQUE INDEX IF NOT EXISTS idx_hosts_name_active ON hosts(name) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS credential_refs(id TEXT PRIMARY KEY,host_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('password','private_key','ssh_agent')), target_name TEXT NOT NULL,secret_location TEXT NOT NULL CHECK(secret_location IN('windows_credential_manager','user_file','ssh_agent')),retention_mode TEXT NOT NULL CHECK(retention_mode IN('never','app_session')),created_at TEXT NOT NULL,last_used_at TEXT,revoked_at TEXT,FOREIGN KEY(host_id) REFERENCES hosts(id) ON DELETE CASCADE,UNIQUE(host_id,kind));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,host_id TEXT NOT NULL,status TEXT NOT NULL,observed_endpoint_fingerprint TEXT,observed_remote_identity_hmac TEXT,pty_rows INTEGER,pty_cols INTEGER,started_at TEXT NOT NULL,ended_at TEXT,disconnect_reason TEXT,FOREIGN KEY(host_id) REFERENCES hosts(id));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id TEXT NOT NULL UNIQUE,event_type TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('info','warning','error','critical')),actor TEXT NOT NULL,target_host_id TEXT,session_id TEXT,correlation_id TEXT,payload_json TEXT NOT NULL,prev_hash TEXT,hash TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(target_host_id) REFERENCES hosts(id),FOREIGN KEY(session_id) REFERENCES sessions(id));
CREATE TABLE IF NOT EXISTS agent_conversations(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,model_provider TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','completed','cancelled','error')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS agent_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,conversation_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('system','user','assistant','tool')),content TEXT,tool_call_json TEXT,created_at TEXT NOT NULL,CHECK(content IS NOT NULL OR tool_call_json IS NOT NULL),FOREIGN KEY(conversation_id) REFERENCES agent_conversations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS command_approvals(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,policy_id TEXT NOT NULL,argv_json TEXT NOT NULL,cwd TEXT,command_hash TEXT NOT NULL,risk TEXT NOT NULL CHECK(risk IN('low','medium','high','critical','blocked')),policy_version INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','approved','rejected','expired','consumed')),created_at TEXT NOT NULL,decided_at TEXT,expires_at TEXT NOT NULL,FOREIGN KEY(session_id) REFERENCES sessions(id),FOREIGN KEY(policy_id) REFERENCES security_policies(id));
CREATE TABLE IF NOT EXISTS execution_records(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,approval_id TEXT,authorization_type TEXT NOT NULL CHECK(authorization_type IN('approval','policy_allowlist','dry_run')),allow_rule_id TEXT,policy_version INTEGER,command_hash TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT,status TEXT NOT NULL CHECK(status IN('running','succeeded','failed','cancelled','blocked')),exit_code INTEGER,stdout_hash TEXT,stderr_hash TEXT,output_bytes INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(session_id) REFERENCES sessions(id),FOREIGN KEY(approval_id) REFERENCES command_approvals(id));
CREATE TABLE IF NOT EXISTS sftp_operations(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('list','read','upload','download','delete','rename','mkdir')),source_path TEXT,destination_path TEXT,size_bytes INTEGER,transferred_bytes INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN('queued','running','paused','completed','failed','cancelled')),overwrite_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(overwrite_confirmed IN(0,1)),content_hash TEXT,error_code TEXT,created_at TEXT NOT NULL,started_at TEXT,ended_at TEXT,FOREIGN KEY(session_id) REFERENCES sessions(id));
CREATE TABLE IF NOT EXISTS audit_exports(id TEXT PRIMARY KEY,format TEXT NOT NULL CHECK(format='jsonl'),filter_json TEXT NOT NULL DEFAULT '{}',event_count INTEGER NOT NULL DEFAULT 0,file_hash TEXT,manifest_hash TEXT,output_path TEXT,status TEXT NOT NULL CHECK(status IN('running','succeeded','failed')),created_at TEXT NOT NULL,completed_at TEXT);
INSERT OR IGNORE INTO security_policies(id,name,mode,version,created_at,updated_at) VALUES('default','默认个人策略','ask_before_execute',1,datetime('now'),datetime('now'));
